'use strict';

/**
* Multiply two 64-bit unsigned integers.
*
* @module @stdlib/number-uint64-base-mul
*
* @example
* import Uint64 from '@stdlib/number-uint64-ctor';
* import mul from '@stdlib/number-uint64-base-mul';
*
* var a = new Uint64( 5 );
* var b = new Uint64( 10 );
*
* var v = mul( a, b );
* // returns <Uint64>[ 50n ]
*/

// MODULES //

import setReadOnly from '@stdlib/utils-define-nonenumerable-read-only-property';
import main from './main.js';
import assign from './assign.js';
import strided from './strided.js';


// MAIN //

setReadOnly( main, 'assign', assign );
setReadOnly( main, 'strided', strided );


// EXPORTS //

export default main;

// exports: { "assign": "main.assign", "strided": "main.strided" }
