'use strict';

// MODULES //

import umul from '@stdlib/number-uint32-base-mul';
import { assign as umuldw } from '@stdlib/number-uint32-base-muldw';


// MAIN //

/**
* Multiplies two 64-bit unsigned integers and assigns results to a provided output array.
*
* @param {uinteger} ah - high 32-bit word of the first 64-bit unsigned integer
* @param {uinteger} al - low 32-bit word of the first 64-bit unsigned integer
* @param {uinteger} bh - high 32-bit word of the second 64-bit unsigned integer
* @param {uinteger} bl - low 32-bit word of the second 64-bit unsigned integer
* @param {Collection} out - output array
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - starting index
* @returns {Collection} output array
*
* @example
* import Uint32Array from '@stdlib/array-uint32';
*
* var out = assign( 1, 2, 3, 4, new Uint32Array( 2 ), 1, 0 );
* // returns <Uint32Array>[ 10, 8 ]
*/
function assign( ah, al, bh, bl, out, stride, offset ) {
	ah >>>= 0;
	al >>>= 0;
	bh >>>= 0;
	bl >>>= 0;

	umuldw( al, bl, out, stride, offset ); // calculates the low 32-bit word of the product and part of high 32-bit word
	out[ offset ] = ( out[ offset ] + umul( ah, bl ) + umul( al, bh ) ) >>> 0; // completes the high 32-bit of the product
	return out;
}


// EXPORTS //

export default assign;
